  1	import type { z } from "zod";
  2	import { type FieldError, ServerErrorCode, errorEnvelopeSchema } from "../schema/error.ts";
  3	
  4	/** Every reason an API call can fail: the API's own codes, plus the ones the app works out when there is no envelope. */
  5	export const ApiErrorCode = {
  6	  ...ServerErrorCode,
  7	  NetworkError: "network_error",
  8	  InvalidResponse: "invalid_response",
  9	  PayloadTooLarge: "payload_too_large",
 10	  Unexpected: "unexpected",
 11	} as const;
 12	
 13	/** One of the `ApiErrorCode` values. */
 14	export type ApiErrorCode = (typeof ApiErrorCode)[keyof typeof ApiErrorCode];
 15	
 16	/** What an `ApiError` is built from. */
 17	export interface ApiErrorInit {
 18	  /** The HTTP status, or 0 when no response came back. */
 19	  readonly status: number;
 20	  readonly code: ApiErrorCode;
 21	  readonly message: string;
 22	  readonly details?: readonly FieldError[];
 23	}
 24	
 25	/** A failed API call, with a code the app can switch on and a message that is safe to show. */
 26	export class ApiError extends Error {
 27	  override readonly name = "ApiError";
 28	  /** The HTTP status, or 0 when no response came back. */
 29	  readonly status: number;
 30	  readonly code: ApiErrorCode;
 31	  readonly details: readonly FieldError[];
 32	
 33	  constructor({ status, code, message, details = [] }: ApiErrorInit) {
 34	    super(message);
 35	    this.status = status;
 36	    this.code = code;
 37	    this.details = details;
 38	  }
 39	}
 40	
 41	/** The methods the API uses. */
 42	export type HttpMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
 43	
 44	/** How to send one request. `ifMatch` is the task version the write expects to find. */
 45	export interface RequestOptions {
 46	  readonly method?: HttpMethod;
 47	  readonly body?: unknown;
 48	  readonly signal?: AbortSignal | undefined;
 49	  readonly ifMatch?: number | undefined;
 50	}
 51	
 52	const derivedMessages = {
 53	  [ApiErrorCode.NetworkError]: "Couldn't reach the server. Check your connection and try again.",
 54	  [ApiErrorCode.ServiceUnavailable]: "The server is busy. Try again in a moment.",
 55	  [ApiErrorCode.PayloadTooLarge]: "That is too much to send in one go.",
 56	  [ApiErrorCode.InvalidResponse]: "The server sent an answer the app couldn't read.",
 57	  [ApiErrorCode.Unexpected]: "Something went wrong on the server.",
 58	} as const;
 59	
 60	type DerivedCode = keyof typeof derivedMessages;
 61	
 62	const derivedError = (status: number, code: DerivedCode): ApiError =>
 63	  new ApiError({ status, code, message: derivedMessages[code] });
 64	
 65	// A proxy or an overloaded server can answer without the API's envelope, so the status is all there is to go on.
 66	const codeForStatus = (status: number): DerivedCode => {
 67	  if (status === 502 || status === 503 || status === 504) return ApiErrorCode.ServiceUnavailable;
 68	  if (status === 413) return ApiErrorCode.PayloadTooLarge;
 69	  return ApiErrorCode.Unexpected;
 70	};
 71	
 72	const headersFor = ({ body, ifMatch }: RequestOptions): Record<string, string> => ({
 73	  Accept: "application/json",
 74	  ...(body === undefined ? {} : { "Content-Type": "application/json" }),
 75	  ...(ifMatch === undefined ? {} : { "If-Match": `"${String(ifMatch)}"` }),
 76	});
 77	
 78	const readJson = (response: Response): Promise<unknown> =>
 79	  response.json().then(
 80	    (body: unknown) => body,
 81	    () => undefined,
 82	  );
 83	
 84	// The query string can hold a search term, which never goes into a log.
 85	const withoutQuery = (path: string): string => path.replace(/\?.*$/, "");
 86	
 87	// fetch rejects with a TypeError when no response arrives; an abort is left alone so TanStack Query sees a cancel.
 88	const send = async (path: string, options: RequestOptions): Promise<Response> => {
 89	  try {
 90	    return await fetch(`/api/v1${path}`, {
 91	      method: options.method ?? "GET",
 92	      credentials: "same-origin",
 93	      headers: headersFor(options),
 94	      body: options.body === undefined ? null : JSON.stringify(options.body),
 95	      signal: options.signal ?? null,
 96	    });
 97	  } catch (error) {
 98	    if (error instanceof TypeError) throw derivedError(0, ApiErrorCode.NetworkError);
 99	    throw error;
100	  }
101	};
102	
103	const errorFrom = async (response: Response): Promise<ApiError> => {
104	  const envelope = errorEnvelopeSchema.safeParse(await readJson(response));
105	  if (!envelope.success) return derivedError(response.status, codeForStatus(response.status));
106	  return new ApiError({ status: response.status, ...envelope.data.error });
107	};
108	
109	const ensureOk = async (response: Response): Promise<Response> => {
110	  if (response.ok) return response;
111	  throw await errorFrom(response);
112	};
113	
114	/** Call the API at `path` (relative to `/api/v1`) and parse the answer with `schema`; any failure is an `ApiError`. */
115	export const apiRequest = async <S extends z.ZodType>(
116	  path: string,
117	  options: RequestOptions & { readonly schema: S },
118	): Promise<z.infer<S>> => {
119	  const response = await ensureOk(await send(path, options));
120	  const parsed = options.schema.safeParse(await readJson(response));
121	  if (parsed.success) return parsed.data;
122	  console.error("[api] response did not match schema", {
123	    path: withoutQuery(path),
124	    issues: parsed.error.issues,
125	  });
126	  throw derivedError(response.status, ApiErrorCode.InvalidResponse);
127	};
128	
129	/** Call an endpoint that answers 204 with no body; any failure is an `ApiError`. */
130	export const apiRequestNoContent = async (path: string, options: RequestOptions): Promise<void> => {
131	  await ensureOk(await send(path, options));
132	};
  1	import { type Task, taskListSchema, taskSchema } from "../schema/task.ts";
  2	import type { TaskChanges } from "../task-draft.ts";
  3	import { apiRequest, apiRequestNoContent } from "./client.ts";
  4	
  5	/** What a new task needs: its title. The server puts it at the top. */
  6	export type NewTask = Pick<Task, "title">;
  7	
  8	/** The fields a PATCH can change; only the ones present are sent. */
  9	export type TaskPatch = TaskChanges & Partial<Pick<Task, "completed">>;
 10	
 11	const taskPath = (taskId: string): string => `/tasks/${encodeURIComponent(taskId)}`;
 12	
 13	const listPath = (q: string): string =>
 14	  q === "" ? "/tasks" : `/tasks?${new URLSearchParams({ q }).toString()}`;
 15	
 16	/** The user's tasks in their order, or only those matching `q` when it is not empty. */
 17	export const listTasks = async (q: string, signal?: AbortSignal): Promise<readonly Task[]> =>
 18	  (await apiRequest(listPath(q), { schema: taskListSchema, signal })).items;
 19	
 20	/** One task. */
 21	export const getTask = (taskId: string, signal?: AbortSignal): Promise<Task> =>
 22	  apiRequest(taskPath(taskId), { schema: taskSchema, signal });
 23	
 24	/** Create a task at the top of the list. */
 25	export const createTask = (input: NewTask): Promise<Task> =>
 26	  apiRequest("/tasks", { method: "POST", body: input, schema: taskSchema });
 27	
 28	/** Change some fields of a task. With `ifMatch`, the server refuses the change if the task is no longer that version. */
 29	export const updateTask = (taskId: string, patch: TaskPatch, ifMatch?: number): Promise<Task> =>
 30	  apiRequest(taskPath(taskId), { method: "PATCH", body: patch, ifMatch, schema: taskSchema });
 31	
 32	/** Put a task right after `afterId`, or at the top when it is null. */
 33	export const moveTask = (taskId: string, afterId: string | null): Promise<Task> =>
 34	  apiRequest(`${taskPath(taskId)}/position`, {
 35	    method: "PUT",
 36	    body: { afterId },
 37	    schema: taskSchema,
 38	  });
 39	
 40	/** Delete a task. */
 41	export const deleteTask = (taskId: string): Promise<void> =>
 42	  apiRequestNoContent(taskPath(taskId), { method: "DELETE" });
  1	import { type Credentials, type User, userSchema } from "../schema/auth.ts";
  2	import { ApiError, ApiErrorCode, apiRequest, apiRequestNoContent } from "./client.ts";
  3	
  4	/** Create an account; the server signs the new user in. */
  5	export const register = (credentials: Credentials): Promise<User> =>
  6	  apiRequest("/auth/register", { method: "POST", body: credentials, schema: userSchema });
  7	
  8	/** Sign in with an email and password. */
  9	export const login = (credentials: Credentials): Promise<User> =>
 10	  apiRequest("/auth/login", { method: "POST", body: credentials, schema: userSchema });
 11	
 12	/** Sign out: the server clears the session cookie. */
 13	export const logout = (): Promise<void> => apiRequestNoContent("/auth/logout", { method: "POST" });
 14	
 15	/** The signed-in user, or null when nobody is signed in, so a visitor is never treated as an expired session. */
 16	export const me = (signal?: AbortSignal): Promise<User | null> =>
 17	  apiRequest("/auth/me", { schema: userSchema, signal }).catch((error: unknown) => {
 18	    if (error instanceof ApiError && error.code === ApiErrorCode.NotAuthenticated) return null;
 19	    throw error;
 20	  });
  1	import { z } from "zod";
  2	
  3	/** Every `code` the API puts in its error envelope. */
  4	export const ServerErrorCode = {
  5	  ValidationFailed: "validation_failed",
  6	  InvalidIfMatch: "invalid_if_match",
  7	  InvalidPosition: "invalid_position",
  8	  NotAuthenticated: "not_authenticated",
  9	  InvalidCredentials: "invalid_credentials",
 10	  ForbiddenOrigin: "forbidden_origin",
 11	  NotFound: "not_found",
 12	  MethodNotAllowed: "method_not_allowed",
 13	  EmailTaken: "email_taken",
 14	  VersionMismatch: "version_mismatch",
 15	  ServiceUnavailable: "service_unavailable",
 16	  InternalError: "internal_error",
 17	} as const;
 18	
 19	/** One problem with one field of a request; `field` is null when the problem is with the request as a whole. */
 20	export const fieldErrorSchema = z.object({
 21	  field: z.string().nullable(),
 22	  message: z.string(),
 23	});
 24	
 25	/** One problem with one field of a request, typed from its schema. */
 26	export type FieldError = z.infer<typeof fieldErrorSchema>;
 27	
 28	/** The one error body every API error carries: `{"error": {"code", "message", "details"}}`. */
 29	export const errorEnvelopeSchema = z.object({
 30	  error: z.object({
 31	    code: z.enum(ServerErrorCode),
 32	    message: z.string(),
 33	    details: z.array(fieldErrorSchema),
 34	  }),
 35	});
