 1	import { MutationCache, QueryCache, QueryClient, type QueryKey } from "@tanstack/react-query";
 2	import { type ApiError, ApiErrorCode } from "../api/client.ts";
 3	
 4	// Every hook's `error` is an ApiError, since every request goes through the fetch wrapper
 5	// (https://tanstack.com/query/v5/docs/framework/react/typescript#registering-a-global-error).
 6	declare module "@tanstack/react-query" {
 7	  interface Register {
 8	    defaultError: ApiError;
 9	  }
10	}
11	
12	/** What the app does when the server says the session has ended. */
13	export interface QueryClientOptions {
14	  readonly onUnauthenticated: () => void;
15	}
16	
17	const retryable: ReadonlySet<ApiErrorCode> = new Set([
18	  ApiErrorCode.NetworkError,
19	  ApiErrorCode.ServiceUnavailable,
20	]);
21	
22	const maxRetries = 2;
23	
24	// Only the first part of a key is logged: the rest can hold a search term.
25	const resourceOf = (key: QueryKey | undefined): string => {
26	  const [resource] = key ?? [];
27	  return typeof resource === "string" ? resource : "unknown";
28	};
