 20	/**
 21	 * The user's tasks, or the matches for `q`. Each term is cached on its own, so a late answer for an older term never
 22	 * replaces a newer one; the previous results stay on screen while the next load; and a superseded request is
 23	 * aborted ([query cancellation](https://tanstack.com/query/v5/docs/framework/react/guides/query-cancellation)).
 24	 */
 25	export const useTasks = (q: string) =>
 26	  useQuery({
 27	    queryKey: taskKeys.list(q),
 28	    queryFn: ({ signal }) => listTasks(q, signal),
 29	    placeholderData: keepPreviousData,
 30	  });
