151	    onSettled: () => {
152	      void client.invalidateQueries({ queryKey: taskKeys.lists() });
153	    },
154	  });
155	};
156	
157	/** A reorder: put the task right after `afterId`, or at the top when it is null. */
158	export interface MoveVariables {
159	  readonly taskId: string;
160	  readonly afterId: string | null;
161	}
162	
163	const moveIn = (items: readonly Task[], { taskId, afterId }: MoveVariables) =>
164	  moveAfter(items, taskId, afterId);
165	
166	/**
167	 * Move a task at once on screen, while the moves themselves reach the server one at a time and in the order the user
168	 * made them: they share one mutation scope ([mutation scopes](https://tanstack.com/query/v5/docs/framework/react/guides/mutations#mutation-scopes)).
169	 * The lists reload only after the last queued move, so a refetch never lands between two of them
170	 * ([concurrent optimistic updates](https://tkdodo.eu/blog/concurrent-optimistic-updates-in-react-query)).
171	 */
172	export const useMoveTask = () => {
173	  const client = useQueryClient();
174	  const updateLists = optimisticListUpdate(client, moveIn);
175	  return useMutation({
176	    mutationKey: taskKeys.mutations.move,
177	    scope: { id: "task-order" },
178	    mutationFn: ({ taskId, afterId }: MoveVariables) => moveTask(taskId, afterId),
179	    onMutate: (vars: MoveVariables) => updateLists(vars),
180	    onError: (error, { taskId }, snapshot) => {
181	      if (isNotFound(error)) forgetTask(client, taskId);
182	      else if (snapshot) restoreLists(client, snapshot);
183	    },
184	    onSettled: () => {
185	      if (client.isMutating({ mutationKey: taskKeys.mutations.move }) === 1)
186	        void client.invalidateQueries({ queryKey: taskKeys.lists() });
187	    },
188	  });
189	};
190	
191	/**
192	 * Add a task. It is not optimistic: the server picks its place at the top, so the list shows it once the server has
193	 * it, and the mutation stays pending until the lists have reloaded with it in.
194	 */
195	export const useCreateTask = () => {
196	  const client = useQueryClient();
197	  return useMutation({
198	    mutationKey: taskKeys.mutations.create,
199	    mutationFn: createTask,
200	    onSuccess: () => client.invalidateQueries({ queryKey: taskKeys.lists() }),
201	  });
202	};
203	
204	const removeFrom = (items: readonly Task[], taskId: string) =>
205	  items.filter((task) => task.id !== taskId);
206	
207	/**
208	 * Delete a task at once: it leaves every cached list and its detail entry before the server answers, and comes back
209	 * if the delete fails. A 404 leaves it gone, since it is gone either way.
210	 */
211	export const useDeleteTask = () => {
212	  const client = useQueryClient();
213	  const updateLists = optimisticListUpdate(client, removeFrom);
214	  return useMutation({
215	    mutationKey: taskKeys.mutations.remove,
216	    mutationFn: deleteTask,
217	    onMutate: async (taskId: string) => {
218	      const lists = await updateLists(taskId);
219	      client.removeQueries({ queryKey: taskKeys.detail(taskId) });
220	      return lists;
221	    },
222	    onError: (error, _taskId, snapshot) => {
223	      if (!isNotFound(error) && snapshot) restoreLists(client, snapshot);
224	    },
225	    onSettled: () => {
226	      void client.invalidateQueries({ queryKey: taskKeys.lists() });
227	    },
228	  });
229	};
230	
231	/**
232	 * The ids of tasks whose delete the server has not answered yet. A list that loads or refetches meanwhile still holds
233	 * them, so the screen leaves them out until the delete settles.
234	 */
235	export const usePendingDeletes = (): ReadonlySet<string> =>
236	  new Set(
237	    useMutationState({
238	      filters: { mutationKey: taskKeys.mutations.remove, status: "pending" },
239	      select: (mutation) => mutation.state.variables,
240	    }).filter((taskId): taskId is string => typeof taskId === "string"),
241	  );
242	
243	type NoticeKind = "toggle" | "move" | "remove" | "create";
244	
245	const noticeKinds: Readonly<Record<string, NoticeKind>> = {
246	  [taskKeys.mutations.toggle[1]]: "toggle",
247	  [taskKeys.mutations.move[1]]: "move",
248	  [taskKeys.mutations.remove[1]]: "remove",
249	  [taskKeys.mutations.create[1]]: "create",
250	};
251	
252	const failedTo: Readonly<Record<NoticeKind, string>> = {
253	  toggle: "Couldn't update the task, so it's back as it was.",
254	  move: "Couldn't move the task, so it's back where it was.",
255	  remove: "Couldn't delete the task, so it's back in the list.",
256	  create: "Couldn't add the task.",
257	};
258	
259	// A delete that finds the task already gone did what the user asked, so there is nothing to tell.
260	const isWorthTelling = (kind: NoticeKind, error: ApiError): boolean =>
261	  !(kind === "remove" && isNotFound(error));
262	
263	// A 404 means someone deleted the task elsewhere; anything else says what was undone and why.
264	const noticeFor = (kind: NoticeKind, error: ApiError): string =>
265	  isNotFound(error) ? "That task was deleted elsewhere." : `${failedTo[kind]} ${error.message}`;
266	
267	const kindOf = (key: MutationKey | undefined): NoticeKind | undefined => {
268	  const [, name] = key ?? [];
269	  return typeof name === "string" ? noticeKinds[name] : undefined;
270	};
271	
272	interface FailedChange {
273	  readonly kind: NoticeKind;
274	  readonly error: ApiError;
275	  readonly submittedAt: number;
276	}
277	
278	/**
279	 * The newest failed list change, wherever it was started (the detail screen included), until the user dismisses it.
280	 * It is read from the mutation cache, so no other store holds it.
281	 */
282	export const useTaskNotices = (): {
283	  readonly notice: string | null;
284	  readonly dismiss: () => void;
285	} => {
286	  const [dismissed, setDismissed] = useState<ReadonlySet<number>>(new Set());
287	  const failures = useMutationState({
288	    filters: { mutationKey: taskKeys.all, status: "error" },
289	    select: (mutation) => ({
290	      kind: kindOf(mutation.options.mutationKey),
291	      error: mutation.state.error,
292	      submittedAt: mutation.state.submittedAt,
293	    }),
294	  });
295	  const newest = failures
296	    .filter(
297	      (failure): failure is FailedChange =>
298	        failure.kind !== undefined &&
299	        failure.error !== null &&
300	        isWorthTelling(failure.kind, failure.error) &&
301	        !dismissed.has(failure.submittedAt),
302	    )
303	    .reduce<FailedChange | null>(
304	      (latest, failure) => (latest && latest.submittedAt >= failure.submittedAt ? latest : failure),
305	      null,
306	    );
307	  return {
308	    notice: newest && noticeFor(newest.kind, newest.error),
309	    dismiss: () => {
310	      if (newest) setDismissed((current) => new Set([...current, newest.submittedAt]));
311	    },
312	  };
313	};
  1	import type { Task } from "../schema/task.ts";
  2	
  3	/**
  4	 * A new list with task `id` placed right after `afterId`, or at the top when it is null. The list comes back unchanged
  5	 * when either task is missing from it, as in a search that doesn't include both.
  6	 */
  7	export const moveAfter = (
  8	  items: readonly Task[],
  9	  id: string,
 10	  afterId: string | null,
 11	): readonly Task[] => {
 12	  const from = items.findIndex((task) => task.id === id);
 13	  const task = items[from];
 14	  if (task === undefined) return items;
 15	  const rest = items.toSpliced(from, 1);
 16	  const to = afterId === null ? 0 : rest.findIndex((other) => other.id === afterId) + 1;
 17	  if (afterId !== null && to === 0) return items;
 18	  return rest.toSpliced(to, 0, task);
 19	};
  1	import { useEffect, useState } from "react";
  2	
  3	/** `value`, but only once it has stopped changing for `delayMs`; each change restarts the wait. */
  4	export const useDebouncedValue = <T>(value: T, delayMs: number): T => {
  5	  const [settled, setSettled] = useState(value);
  6	  // A timer lives outside React, so an effect owns it and clears it when the value changes again.
  7	  useEffect(() => {
  8	    const timer = setTimeout(() => {
  9	      setSettled(value);
 10	    }, delayMs);
 11	    return () => {
 12	      clearTimeout(timer);
 13	    };
 14	  }, [value, delayMs]);
 15	  return settled;
 16	};

