  9	import { detailTask, makeTask, tasks } from "../test/fixtures.ts";
 10	import { errorReply } from "../test/handlers.ts";
 11	import { renderApp } from "../test/render-app.tsx";
 12	import { server } from "../test/server.ts";
 13	
 14	const taskTitles = (): readonly string[] =>
 15	  within(screen.getByRole("list", { name: "Tasks" }))
 16	    .getAllByRole("link")
 17	    .map((link) => link.textContent);
 18	
 19	const titleAt = (index: number): string => {
 20	  const task = tasks[index];
 21	  if (!task) throw new Error(`the fixtures have no task at ${String(index)}`);
 22	  return task.title;
 23	};
 24	
 25	const moveBodySchema = z.object({ afterId: z.string().nullable() });
 26	
 27	// The server's side of a move: take the task out, then put it back right after `afterId`.
 28	const serverMove = (ids: readonly string[], id: string, afterId: string | null) => {
 29	  const rest = ids.filter((other) => other !== id);
 30	  return rest.toSpliced(afterId === null ? 0 : rest.indexOf(afterId) + 1, 0, id);
 31	};
 32	
 33	// A server that keeps the order in memory and answers each move later than the one sent after it.
 34	const reorderingServer = () => {
 35	  const byId = new Map(tasks.map((task) => [task.id, task]));
 36	  const state = { ids: tasks.map((task) => task.id), movesReceived: 0 };
 37	  const moveDelaysMs = [300, 200, 100];
 38	  server.use(
 39	    http.get("/api/v1/tasks", async () => {
 40	      await delay(150);
 41	      return HttpResponse.json({ items: state.ids.map((id) => byId.get(id)) });
 42	    }),
 43	    http.put("/api/v1/tasks/:taskId/position", async ({ params, request }) => {
 44	      const taskId = String(params.taskId);
 45	      const { afterId } = moveBodySchema.parse(await request.json());
 46	      const wait = moveDelaysMs[state.movesReceived] ?? 0;
 47	      state.movesReceived += 1;
 48	      await delay(wait);
 49	      state.ids = serverMove(state.ids, taskId, afterId);
 50	      return HttpResponse.json(byId.get(taskId));
 51	    }),
 52	  );
 53	};
 54	
 55	const tickBox = (title: string) => screen.getByRole("checkbox", { name: `Completed: ${title}` });
 56	
 57	const renderList = async () => {
 58	  const app = renderApp(routes.tasks);
 59	  await screen.findByRole("list", { name: "Tasks" });
 60	  return app;
 61	};
 62	
 63	describe("TaskListPage", () => {
 64	  it("shows the server's tasks after loading", async () => {
 65	    renderApp(routes.tasks);
 66	
 67	    expect(await screen.findByRole("list", { name: "Tasks" })).toBeVisible();
 68	    expect(taskTitles()).toEqual(tasks.map((task) => task.title));
 69	  });
 70	
 71	  it("disables reorder while a search is typed", async () => {
 72	    await renderList();
 73	    expect(screen.getAllByRole("button", { name: /^Move / })).toHaveLength(tasks.length);
 74	
 75	    await userEvent.type(screen.getByRole("searchbox", { name: "Search tasks" }), "budget");
 76	
 77	    expect(screen.queryAllByRole("button", { name: /^Move / })).toHaveLength(0);
 78	  });
 79	
 80	  it("three quick moves end in the order the user made", async () => {
 81	    stackRows();
 82	    reorderingServer();
 83	    const app = await renderList();
 84	    const refetchLists = () => {
 85	      void app.client.refetchQueries({ queryKey: taskKeys.lists() });
