 87	
 88	    // The moves overlap, so the server ends in the user's order only if it applies them in the order they were made.
 89	    await moveOnePlace(titleAt(0), "down");
 90	    refetchLists();
 91	    await moveOnePlace(titleAt(2), "up");
 92	    refetchLists();
