106	  it("rolls back an optimistic toggle and says what failed", async () => {
107	    vi.spyOn(console, "error").mockImplementation(() => undefined);
108	    await renderList();
109	    // The refetch after the failure answers late, so what the test sees is the rollback, not fresh data.
110	    server.use(
