  1	import { type QueryClient, QueryClientProvider } from "@tanstack/react-query";
  2	import { render } from "@testing-library/react";
  3	import { type DataRouter, createMemoryRouter } from "react-router";
  4	import { RouterProvider } from "react-router/dom";
  5	import { appRoutes, goToSignIn } from "../app/router.tsx";
  6	import { createQueryClient } from "../lib/query/client.ts";
  7	
  8	/** What a test gets back from `renderApp`: the router, to read the location, and the query client. */
  9	export interface RenderedApp {
 10	  readonly router: DataRouter;
 11	  readonly client: QueryClient;
 12	}
 13	
 14	/** Render the whole app at `path`, wired the way `main.tsx` wires it, with history kept in memory. */
 15	export const renderApp = (path: string): RenderedApp => {
 16	  const router = createMemoryRouter(appRoutes, { initialEntries: [path] });
 17	  const client = createQueryClient({ onUnauthenticated: goToSignIn(router) });
 18	  render(
 19	    <QueryClientProvider client={client}>
 20	      <RouterProvider router={router} />
 21	    </QueryClientProvider>,
 22	  );
 23	  return { router, client };
 24	};
  1	import { HttpResponse, http } from "msw";
