  4	
  5	type ServerCode = (typeof ServerErrorCode)[keyof typeof ServerErrorCode];
  6	
  7	/** An API error reply in the envelope every endpoint uses. */
  8	export const errorReply = (
  9	  status: number,
 10	  code: ServerCode,
 11	  details: readonly FieldError[] = [],
 12	): HttpResponse<{ error: { code: ServerCode; message: string; details: readonly FieldError[] } }> =>
 13	  HttpResponse.json({ error: { code, message: `The API said ${code}.`, details } }, { status });
 14	
 15	// The detail screen's task first, so its id opens the fuller version of that task.
 16	const findTask = (taskId: unknown) => [detailTask, ...tasks].find((task) => task.id === taskId);
 17	
 18	/** The API's happy path for a signed-in user, answered from the shared fixtures. */
 19	export const handlers = [
