 10	
 11	const notFoundHeading = { name: "This task isn't in your ledger" };
 12	const taskUrl = `/api/v1/tasks/${detailTask.id}`;
 13	
 14	describe("app router", () => {
 15	  it("shows not found for another user's task id", async () => {
 16	    vi.spyOn(console, "error").mockImplementation(() => undefined);
 17	    renderApp(routes.task("7b0c1e5a-0000-4000-8000-00000000ffff"));
 18	
 19	    expect(await screen.findByRole("heading", notFoundHeading)).toBeVisible();
 20	  });
 21	
 22	  it("shows not found for an unknown route", async () => {
 23	    renderApp("/ledger/nowhere");
 24	
 25	    expect(
 26	      await screen.findByRole("heading", { name: "This page isn't in the ledger" }),
 27	    ).toBeVisible();
 28	  });
 29	
 30	  it("shows the error screen when a task fails to load", async () => {
 31	    vi.spyOn(console, "error").mockImplementation(() => undefined);
 32	    server.use(http.get(taskUrl, () => errorReply(500, "internal_error")));
 33	    renderApp(routes.task(detailTask.id));
 34	
 35	    expect(await screen.findByRole("heading", { name: "Something went wrong" })).toBeVisible();
 36	  });
 37	
 38	  it("loads the page again from the error screen", async () => {
 39	    vi.spyOn(console, "error").mockImplementation(() => undefined);
 40	    const state = { failed: false };
 41	    server.use(
 42	      http.get(taskUrl, () => {
 43	        if (state.failed) return HttpResponse.json(detailTask);
 44	        state.failed = true;
 45	        return errorReply(500, "internal_error");
 46	      }),
 47	    );
 48	    renderApp(routes.task(detailTask.id));
 49	
 50	    await userEvent.click(await screen.findByRole("button", { name: "Try again" }));
 51	
 52	    expect(await screen.findByRole("heading", { level: 1, name: detailTask.title })).toBeVisible();
 53	  });
 54	
 55	  it("goes to the task list from the error screen", async () => {
 56	    vi.spyOn(console, "error").mockImplementation(() => undefined);
 57	    server.use(http.get(taskUrl, () => errorReply(500, "internal_error")));
 58	    const { router } = renderApp(routes.task(detailTask.id));
 59	
 60	    await userEvent.click(await screen.findByRole("button", { name: "Go to tasks" }));
 61	
 62	    expect(await screen.findByRole("list", { name: "Tasks" })).toBeVisible();
 63	    expect(router.state.location.pathname).toBe(routes.tasks);
 64	  });
 65	
 66	  it("shows not found for a task id that is not a UUID, without asking the server", async () => {
 67	    const taskRequests = vi.fn<() => void>();
 68	    server.use(
 69	      http.get("/api/v1/tasks/:taskId", () => {
 70	        taskRequests();
 71	        return errorReply(404, "not_found");
 72	      }),
 73	    );
 74	    renderApp(routes.task("not-a-task"));
 75	
 76	    expect(await screen.findByRole("heading", notFoundHeading)).toBeVisible();
 77	    expect(taskRequests).not.toHaveBeenCalled();
 78	  });
 79	
 80	  it("sends a signed-out visitor to sign-in with a return path", async () => {
 81	    server.use(http.get("/api/v1/auth/me", () => errorReply(401, "not_authenticated")));
 82	    const { router } = renderApp("/tasks?q=boiler");
 83	
 84	    expect(await screen.findByRole("heading", { name: "Sign in" })).toBeVisible();
