 94	      http.get("/api/v1/auth/me", () =>
 95	        session.ended ? errorReply(401, "not_authenticated") : HttpResponse.json(user),
 96	      ),
 97	      http.get("/api/v1/tasks", () => {
 98	        session.ended = true;
 99	        return errorReply(401, "not_authenticated");
100	      }),
101	    );
102	    const { router } = renderApp(routes.tasks);
103	
104	    expect(await screen.findByRole("heading", { name: "Sign in" })).toBeVisible();
105	    await delay(100);
106	
107	    expect(screen.getByRole("heading", { name: "Sign in" })).toBeVisible();
108	    expect(router.state.location.pathname + router.state.location.search).toBe(
109	      signInPath(routes.tasks),
110	    );
111	  });
112	
113	  it("signs out and returns to sign-in", async () => {
114	    const session = { signedIn: true };
115	    server.use(
116	      http.get("/api/v1/auth/me", () =>
117	        session.signedIn ? HttpResponse.json(user) : errorReply(401, "not_authenticated"),
118	      ),
