120	        session.signedIn = false;
121	        return new HttpResponse(null, { status: 204 });
122	      }),
123	    );
124	    const { router } = renderApp("/tasks");
125	
126	    await userEvent.click(await screen.findByRole("button", { name: "Sign out" }));
127	
128	    expect(await screen.findByRole("heading", { name: "Sign in" })).toBeVisible();
129	    await waitFor(() => {
130	      expect(router.state.location.pathname).toBe("/sign-in");
131	    });
132	  });
133	});
  1	import { QueryClientProvider, useMutation } from "@tanstack/react-query";
  2	import { renderHook } from "@testing-library/react";
  3	import { http } from "msw";
  4	import type { ReactNode } from "react";
  5	import { describe, expect, it, vi } from "vitest";
  6	import { tasks, user } from "../../test/fixtures.ts";
  7	import { errorReply } from "../../test/handlers.ts";
  8	import { server } from "../../test/server.ts";
  9	import { login } from "../api/auth.ts";
 10	import { listTasks } from "../api/tasks.ts";
 11	import { createQueryClient } from "./client.ts";
 12	import { authKeys, taskKeys } from "./keys.ts";
 13	
 14	const credentials = { email: user.email, password: "correct horse battery" };
 15	
 16	describe("createQueryClient", () => {
 17	  it("clears the cache and goes to sign-in with a return path on not_authenticated", async () => {
 18	    server.use(http.get("/api/v1/tasks", () => errorReply(401, "not_authenticated")));
 19	    const onUnauthenticated = vi.fn<() => void>();
 20	    const client = createQueryClient({ onUnauthenticated });
 21	    client.setQueryData(authKeys.me, user);
 22	
 23	    await client
 24	      .query({ queryKey: taskKeys.list(""), queryFn: ({ signal }) => listTasks("", signal) })
 25	      .catch(() => undefined);
 26	
 27	    expect(onUnauthenticated).toHaveBeenCalledOnce();
 28	    expect(client.getQueryData(authKeys.me)).toBeUndefined();
 29	  });
 30	
 31	  it("does not redirect on invalid_credentials", async () => {
 32	    vi.spyOn(console, "error").mockImplementation(() => undefined);
 33	    server.use(http.post("/api/v1/auth/login", () => errorReply(401, "invalid_credentials")));
 34	    const onUnauthenticated = vi.fn<() => void>();
 35	    const client = createQueryClient({ onUnauthenticated });
 36	    client.setQueryData(taskKeys.list(""), tasks);
 37	    const wrapper = ({ children }: { readonly children: ReactNode }) => (
 38	      <QueryClientProvider client={client}>{children}</QueryClientProvider>
 39	    );
 40	    const { result } = renderHook(() => useMutation({ mutationFn: login }), { wrapper });
 41	
 42	    await result.current.mutateAsync(credentials).catch(() => undefined);
 43	
 44	    expect(onUnauthenticated).not.toHaveBeenCalled();
 45	    expect(client.getQueryData(taskKeys.list(""))).toEqual(tasks);
 46	  });
 47	});

