export const makeTask = (overrides: Partial<Task> = {}): Task =>
  taskSchema.parse({
    id: "00000000-0000-4000-8000-000000000000",
    title: "Water the plants",
    notes: "",
    completed: false,
    dueDate: null,
    rank: "a0",
    version: 1,
    createdAt: "2026-10-12T08:30:00Z",
    updatedAt: "2026-10-12T08:30:00Z",
