cd /private/tmp/claude-501/-Users-ag-Documents-dev-artemis-todo-app/fa9c58ff-72fc-4042-9fe7-6e07e6e2c359/scratchpad/wt/frontend/src && cat > pages/probe.test.tsx <<'EOF'
import { focusManager } from "@tanstack/react-query";
import { act, screen, waitFor, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { HttpResponse, delay, http } from "msw";
import { afterEach, describe, expect, it, vi } from "vitest";
import { taskKeys } from "../lib/query/keys.ts";
import { routes } from "../lib/routes.ts";
import { moveOnePlace, stackRows } from "../test/drag.ts";
import { detailTask, tasks, user } from "../test/fixtures.ts";
import { errorReply } from "../test/handlers.ts";
import { renderApp } from "../test/render-app.tsx";
import { server } from "../test/server.ts";

const tickBox = (title: string) => screen.getByRole("checkbox", { name: `Completed: ${title}` });
const titles = () =>
  within(screen.getByRole("list", { name: "Tasks" }))
    .getAllByRole("link")
    .map((l) => l.textContent);

describe("probes", () => {
  afterEach(() => {
    focusManager.setFocused(undefined);
  });

  it("P1: a 401 on a toggle leaves no task list in the cache", async () => {
    vi.spyOn(console, "error").mockImplementation(() => undefined);
    const session = { ended: false };
    server.use(
      http.get("/api/v1/auth/me", () =>
        session.ended ? errorReply(401, "not_authenticated") : HttpResponse.json(user),
      ),
      http.patch("/api/v1/tasks/:taskId", () => {
        session.ended = true;
        return errorReply(401, "not_authenticated");
      }),
    );
    const app = renderApp(routes.tasks);
    await screen.findByRole("list", { name: "Tasks" });
    await userEvent.click(tickBox(detailTask.title));
    expect(await screen.findByRole("heading", { name: "Sign in" })).toBeVisible();
    await delay(100);
    console.log("P1 cached lists:", JSON.stringify(app.client.getQueriesData({ queryKey: taskKeys.lists() }).map(([k, v]) => [k, Array.isArray(v) ? v.length : v])));
    expect(app.client.getQueryData(taskKeys.list(""))).toBeUndefined();
  });

  it("P2: a dismissed notice stays dismissed after visiting a task and coming back", async () => {
    vi.spyOn(console, "error").mockImplementation(() => undefined);
    server.use(http.patch("/api/v1/tasks/:taskId", () => errorReply(500, "internal_error")));
    const app = renderApp(routes.tasks);
    await screen.findByRole("list", { name: "Tasks" });
    await userEvent.click(tickBox(detailTask.title));
    await userEvent.click(within(await screen.findByRole("alert")).getByRole("button", { name: "Dismiss" }));
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
    await act(() => app.router.navigate(routes.task(detailTask.id)));
    await screen.findByRole("button", { name: "Edit task" });
    await act(() => app.router.navigate(routes.tasks));
    await screen.findByRole("list", { name: "Tasks" });
    await delay(50);
    expect(screen.queryByRole("alert")).not.toBeInTheDocument();
  });

  it("P3: a focus refetch while moves are queued never shows a half-applied order", async () => {
    stackRows();
    const ids = { list: tasks.map((t) => t.id) };
    const byId = new Map(tasks.map((t) => [t.id, t]));
    server.use(
      http.get("/api/v1/tasks", async () => {
        await delay(20);
        return HttpResponse.json({ items: ids.list.map((id) => byId.get(id)) });
      }),
      http.put("/api/v1/tasks/:taskId/position", async ({ params, request }) => {
        const body = (await request.json()) as { afterId: string | null };
        await delay(200);
        const rest = ids.list.filter((x) => x !== params.taskId);
        ids.list = rest.toSpliced(body.afterId === null ? 0 : rest.indexOf(body.afterId) + 1, 0, String(params.taskId));
        return HttpResponse.json(byId.get(String(params.taskId)));
      }),
    );
    const app = renderApp(routes.tasks);
    await screen.findByRole("list", { name: "Tasks" });
    const first = tasks[0]?.title ?? "";
    const third = tasks[2]?.title ?? "";
    await moveOnePlace(first, "down");
    await moveOnePlace(third, "up");
    const intended = titles();
    act(() => {
      focusManager.setFocused(false);
      focusManager.setFocused(true);
    });
    const seen: string[][] = [];
    await waitFor(
      () => {
        seen.push([...titles()]);
        expect(app.client.isMutating() + app.client.isFetching()).toBe(0);
      },
      { timeout: 3000, interval: 10 },
    );
    const distinct = new Set(seen.map((s) => s.join("|")));
    console.log("P3 distinct orders seen:", distinct.size);
    expect(titles()).toEqual(intended);
    expect(seen.every((s) => s.join("|") === intended.join("|"))).toBe(true);
  });

  it("P4: a failed background refetch keeps the draft", async () => {
    vi.spyOn(console, "error").mockImplementation(() => undefined);
    renderApp(routes.task(detailTask.id));
    await userEvent.click(await screen.findByRole("button", { name: "Edit task" }));
    const title = screen.getByRole("textbox", { name: "Title" });
    await userEvent.clear(title);
    await userEvent.type(title, "My unsaved title");
    server.use(http.get(`/api/v1/tasks/${detailTask.id}`, () => errorReply(500, "internal_error")));
    act(() => {
      focusManager.setFocused(false);
      focusManager.setFocused(true);
    });
    await delay(200);
    expect(screen.queryByRole("heading", { name: "Something went wrong" })).not.toBeInTheDocument();
    expect(screen.getByRole("textbox", { name: "Title" })).toHaveValue("My unsaved title");
  });
});
EOF
